--
-- Name: delegated_authority_grants_revoke_only(); Type: FUNCTION; Schema: proxima_core; Owner: -
--

CREATE FUNCTION proxima_core.delegated_authority_grants_revoke_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW IS NOT DISTINCT FROM OLD THEN
        RETURN NEW;
    END IF;

    IF OLD.revoked_at IS NOT NULL
       OR OLD.revoked_by_user_id IS NOT NULL
       OR NEW.revoked_at IS NULL
       OR NEW.revoked_by_user_id IS NULL
       OR ROW(
            NEW.delegation_id,
            NEW.subject_user_id,
            NEW.owner_kind,
            NEW.owner_id,
            NEW.tool_name,
            NEW.action_name,
            NEW.read_ceiling,
            NEW.write_ceiling,
            NEW.expires_at,
            NEW.auth_epoch,
            NEW.issued_at
          ) IS DISTINCT FROM ROW(
            OLD.delegation_id,
            OLD.subject_user_id,
            OLD.owner_kind,
            OLD.owner_id,
            OLD.tool_name,
            OLD.action_name,
            OLD.read_ceiling,
            OLD.write_ceiling,
            OLD.expires_at,
            OLD.auth_epoch,
            OLD.issued_at
          ) THEN
        RAISE EXCEPTION
            'delegated authority grant is immutable except for first revocation';
    END IF;

    RETURN NEW;
END;
$$;


