--
-- Name: lexical_language_forget(regconfig); Type: FUNCTION; Schema: proxima_core; Owner: -
--

CREATE FUNCTION proxima_core.lexical_language_forget(config_to_forget regconfig) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    holder record;
    found  boolean;
    locked boolean;
BEGIN
    IF config_to_forget IS NULL THEN
        RAISE EXCEPTION 'lexical configuration must not be null';
    END IF;
    IF config_to_forget = proxima_core.lexical_config() THEN
        RAISE EXCEPTION 'cannot forget %: it is the default lexical configuration',
            config_to_forget;
    END IF;

    -- Lock the registration row BEFORE scanning. Writers stamping a row in
    -- this language hold FOR KEY SHARE on it until their transaction ends
    -- (see register_lexical_language_in_tx), and FOR UPDATE conflicts with
    -- that — so this blocks until every in-flight write in the language has
    -- committed, and the scan below then sees their rows. Without the
    -- lock, forget is a check-then-delete that a concurrent write slips
    -- past, committing rows in a language that no longer matches anything.
    SELECT true INTO locked
      FROM proxima_core.lexical_languages
     WHERE config = config_to_forget
       FOR UPDATE;
    IF locked IS NOT TRUE THEN
        RETURN; -- not registered: nothing to forget
    END IF;

    FOR holder IN
        SELECT n.nspname AS s, c.relname AS t, a.attname AS col
          FROM pg_attribute a
          JOIN pg_class     c ON c.oid = a.attrelid
          JOIN pg_namespace n ON n.oid = c.relnamespace
         WHERE a.atttypid = 'regconfig'::regtype
           AND a.attnum > 0
           AND NOT a.attisdropped
           -- 'm': a materialized view stores regconfig values as durably as
           -- a table and dangles the same way after a config drop. Foreign
           -- tables ('f') are deliberately NOT scanned — probing one
           -- queries the remote server, which may hang or error; foreign
           -- holders are the operator's own responsibility.
           AND c.relkind IN ('r', 'p', 'm')
           AND NOT (n.nspname = 'proxima_core' AND c.relname = 'lexical_languages')
         ORDER BY n.nspname, c.relname, a.attname
    LOOP
        EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I.%I WHERE %I = %L::regconfig)',
                       holder.s, holder.t, holder.col, config_to_forget::text)
           INTO found;
        IF found THEN
            RAISE EXCEPTION 'cannot forget %: rows in %.% still reference it (column %)',
                config_to_forget, holder.s, holder.t, holder.col;
        END IF;
    END LOOP;

    DELETE FROM proxima_core.lexical_languages
     WHERE config = config_to_forget;
END
$$;


--
-- Name: FUNCTION lexical_language_forget(config_to_forget regconfig); Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON FUNCTION proxima_core.lexical_language_forget(config_to_forget regconfig) IS 'Remove a configuration from the active-language set, refusing while any table or materialized-view row still holds it in a regconfig column (foreign tables are not scanned). Serialized against in-flight writes via the registration row lock. Run this BEFORE dropping a custom text search configuration: PostgreSQL allows the drop with rows still referencing it, and those rows are then un-updatable (cache lookup failed on the dangling OID).';


--
-- Name: lexical_query_text(regconfig, text); Type: FUNCTION; Schema: proxima_core; Owner: -
--

CREATE FUNCTION proxima_core.lexical_query_text(config regconfig, query_text text) RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT CASE
       WHEN config = 'simple'::regconfig THEN
           (SELECT COALESCE(string_agg(tok, ' '), '')
              FROM regexp_split_to_table(query_text, '\s+') AS tok
             WHERE tok <> ''
               AND to_tsvector(proxima_core.lexical_config(), tok) <> '')
       ELSE query_text
   END $$;


--
-- Name: FUNCTION lexical_query_text(config regconfig, query_text text); Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON FUNCTION proxima_core.lexical_query_text(config regconfig, query_text text) IS 'The query text to parse under one configuration when building the cross-language match OR. For stop-list-free configurations (simple), tokens that the default configuration treats as stopwords are removed first, so function words never become match terms; every other configuration receives the text unchanged. Query-side only — stored vectors keep every token their row''s configuration keeps.';


--
-- Name: lexical_scrub(text); Type: FUNCTION; Schema: proxima_core; Owner: -
--

CREATE FUNCTION proxima_core.lexical_scrub(txt text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$ SELECT regexp_replace(
       regexp_replace(txt, '[[:punct:]]+', ' ', 'g'),
       '\m[[:alnum:]]{255}[[:alnum:]]+\M', ' ', 'g') $$;


--
-- Name: FUNCTION lexical_scrub(txt text); Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON FUNCTION proxima_core.lexical_scrub(txt text) IS 'Punctuation and over-long-token scrub applied before lexical tokenisation. Kept in one place so stored columns and the query builder cannot diverge.';


