COMMENT ON FUNCTION proxima_core.lexical_tsv(config regconfig, txt text) IS 'The canonical lexical vector for one text blob under an explicit text-search configuration. Stored search_tsv columns generate through this with the row''s lexical_language, so the language a text was tokenised with is data on the row, not a function definition that can drift.';


--
-- Name: memories_enforce_immutable(); Type: FUNCTION; Schema: proxima_core; Owner: -
--

CREATE FUNCTION proxima_core.memories_enforce_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.memory_id IS DISTINCT FROM OLD.memory_id
        OR NEW.schema_id IS DISTINCT FROM OLD.schema_id
        OR NEW.schema_version IS DISTINCT FROM OLD.schema_version
        OR NEW.receipt_id IS DISTINCT FROM OLD.receipt_id
        OR NEW.kind IS DISTINCT FROM OLD.kind
        OR NEW.text IS DISTINCT FROM OLD.text
        OR NEW.operator_kind IS DISTINCT FROM OLD.operator_kind
        OR NEW.operator_id IS DISTINCT FROM OLD.operator_id
        OR NEW.input_contract_id IS DISTINCT FROM OLD.input_contract_id
        OR NEW.source_batch_id IS DISTINCT FROM OLD.source_batch_id
        OR NEW.model_id IS DISTINCT FROM OLD.model_id
        OR NEW.prompt_version IS DISTINCT FROM OLD.prompt_version
        OR NEW.lexical_language IS DISTINCT FROM OLD.lexical_language
    THEN
        RAISE EXCEPTION 'memories append-only: immutable column changed on memory_id=%', OLD.memory_id;
    END IF;
    RETURN NEW;
END;
$$;


