-- Name: memory_entity_kind(proxima_core.entity_kind); Type: FUNCTION; Schema: proxima_core; Owner: -
--

CREATE FUNCTION proxima_core.memory_entity_kind(kind proxima_core.entity_kind) RETURNS proxima_core.entity_kind
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT COALESCE(kind, 'Fact'::proxima_core.entity_kind);
$$;


--
-- Name: set_lexical_config(regconfig); Type: FUNCTION; Schema: proxima_core; Owner: -
--

CREATE FUNCTION proxima_core.set_lexical_config(new_config regconfig) RETURNS TABLE(rebuilt_schema text, rebuilt_table text, rebuilt_column text)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    target record;
BEGIN
    IF new_config IS NULL THEN
        RAISE EXCEPTION 'lexical configuration must not be null';
    END IF;

    EXECUTE format(
        'CREATE OR REPLACE FUNCTION proxima_core.lexical_config() RETURNS regconfig '
        'LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $body$ SELECT %L::regconfig $body$',
        new_config::text);

    -- The new default is a language rows will now be written in.
    INSERT INTO proxima_core.lexical_languages (config)
    VALUES (new_config)
    ON CONFLICT (config) DO NOTHING;

    -- pg_catalog rather than information_schema: the latter hides columns
    -- from roles without privileges on the table, and a silently skipped
    -- table is exactly the split-brain this function exists to prevent.
    FOR target IN
        SELECT n.nspname AS s, c.relname AS t, a.attname AS col,
               pg_get_expr(d.adbin, d.adrelid) AS expr
          FROM pg_attribute a
          JOIN pg_class     c ON c.oid = a.attrelid
          JOIN pg_namespace n ON n.oid = c.relnamespace
          JOIN pg_attrdef   d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
         WHERE a.attgenerated = 's'
           AND NOT a.attisdropped
           AND EXISTS (
               SELECT 1
                 FROM pg_depend dep
                WHERE dep.classid = 'pg_attrdef'::regclass
                  AND dep.objid = d.oid
                  AND dep.refclassid = 'pg_proc'::regclass
                  AND dep.refobjid IN (
                      to_regprocedure('proxima_core.lexical_config()')::oid,
                      to_regprocedure('proxima_core.lexical_tsv(text)')::oid))
         ORDER BY n.nspname, c.relname, a.attname
    LOOP
        -- Re-applying the identical expression is what forces the rewrite;
        -- the expression's *value* changed because lexical_config() did.
        EXECUTE format('ALTER TABLE %I.%I ALTER COLUMN %I SET EXPRESSION AS (%s)',
                       target.s, target.t, target.col, target.expr);
        rebuilt_schema := target.s;
        rebuilt_table  := target.t;
        rebuilt_column := target.col;
        RETURN NEXT;
    END LOOP;
END
$_$;


--
-- Name: FUNCTION set_lexical_config(new_config regconfig); Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON FUNCTION proxima_core.set_lexical_config(new_config regconfig) IS 'Set the DEFAULT lexical text-search configuration: rows written without an explicit or detected language use it from now on. Existing rows keep the language they were stamped with. Stored vectors still generated through the one-argument lexical_tsv/lexical_config (pre-per-row flavor sidecars) are rebuilt in the same transaction, each under an ACCESS EXCLUSIVE table rewrite — returns those columns; per-row columns are untouched.';


--
-- Name: sidecar_lexical_language_from_memory(); Type: FUNCTION; Schema: proxima_core; Owner: -
--

CREATE FUNCTION proxima_core.sidecar_lexical_language_from_memory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    memory_language regconfig;
BEGIN
    SELECT m.lexical_language INTO memory_language
      FROM proxima_core.memories m
     WHERE m.memory_id = NEW.memory_id;
    IF memory_language IS NOT NULL THEN
        NEW.lexical_language := memory_language;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION sidecar_lexical_language_from_memory(); Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON FUNCTION proxima_core.sidecar_lexical_language_from_memory() IS 'BEFORE INSERT: stamp the sidecar row''s lexical_language from its owning memories row, so the sidecar''s stored vector tokenises with the same language as the memory''s. Ingest inserts the memories row first in the same transaction; a sidecar inserted without one (test fixtures) keeps its column default.';


--
-- Name: validate_edge_invariants(); Type: FUNCTION; Schema: proxima_core; Owner: -
--

CREATE FUNCTION proxima_core.validate_edge_invariants() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_actual proxima_core.edge_endpoint_kind;
    source_owner_kind proxima_core.owner_ref_kind;
    source_owner_id uuid;
    target_actual proxima_core.edge_endpoint_kind;
BEGIN
    SELECT actual_kind, owner_kind, owner_id
      INTO source_actual, source_owner_kind, source_owner_id
      FROM proxima_core.edge_endpoint_row(NEW.source_kind, NEW.source_id);
    IF source_actual IS NULL THEN
        RAISE EXCEPTION 'edge: source endpoint not found';
    END IF;
    IF source_actual <> NEW.source_kind THEN
        RAISE EXCEPTION 'edge: source kind % does not match endpoint kind %',
            NEW.source_kind, source_actual;
    END IF;

    SELECT actual_kind INTO target_actual
      FROM proxima_core.edge_endpoint_row(NEW.target_kind, NEW.target_id);
    IF target_actual IS NULL THEN
        RAISE EXCEPTION 'edge: target endpoint not found';
    END IF;
    IF target_actual <> NEW.target_kind THEN
        RAISE EXCEPTION 'edge: target kind % does not match endpoint kind %',
            NEW.target_kind, target_actual;
    END IF;

    IF source_owner_kind <> NEW.owner_kind
       OR source_owner_id IS DISTINCT FROM NEW.owner_id THEN
        RAISE EXCEPTION 'edge: owner is not the source owner';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: tsquery_or_agg(tsquery); Type: AGGREGATE; Schema: proxima_core; Owner: -
--

CREATE AGGREGATE proxima_core.tsquery_or_agg(tsquery) (
    SFUNC = tsquery_or,
    STYPE = tsquery,
    COMBINEFUNC = tsquery_or,
    PARALLEL = safe
);


--
-- Name: AGGREGATE tsquery_or_agg(tsquery); Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON AGGREGATE proxima_core.tsquery_or_agg(tsquery) IS 'OR-combines tsqueries, used by the search builder to build one match query across every active lexical language. Empty tsqueries fold away; an empty input set yields NULL (callers COALESCE to the default configuration''s query).';




