--
-- Name: change_event; Type: TABLE; Schema: proxima_core; Owner: -
--

CREATE TABLE proxima_core.change_event (
    seq uuid NOT NULL,
    owner_kind proxima_core.owner_ref_kind NOT NULL,
    owner_id uuid,
    kind proxima_core.change_event_kind NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    entity_kind proxima_core.entity_kind,
    entity_memory_id uuid,
    entity_goal_id uuid,
    entity_schema_id text,
    entity_schema_version integer,
    supersedes_memory_id uuid,
    supersedes_goal_id uuid,
    edge_kind proxima_core.edge_kind,
    edge_source_kind proxima_core.edge_endpoint_kind,
    edge_source_id uuid,
    edge_target_kind proxima_core.edge_endpoint_kind,
    edge_target_id uuid,
    CONSTRAINT change_event_endpoint_chk CHECK (
CASE
    WHEN (kind = ANY (ARRAY['EdgeAppend'::proxima_core.change_event_kind, 'EdgeDelete'::proxima_core.change_event_kind])) THEN ((entity_kind IS NULL) AND (entity_memory_id IS NULL) AND (entity_goal_id IS NULL) AND (entity_schema_id IS NULL) AND (entity_schema_version IS NULL) AND (supersedes_memory_id IS NULL) AND (supersedes_goal_id IS NULL) AND (edge_kind IS NOT NULL) AND (edge_source_kind IS NOT NULL) AND (edge_source_id IS NOT NULL) AND (edge_target_kind IS NOT NULL) AND (edge_target_id IS NOT NULL))
    ELSE ((num_nonnulls(entity_memory_id, entity_goal_id) = 1) AND (entity_kind IS NOT NULL) AND (entity_schema_id IS NOT NULL) AND (entity_schema_version IS NOT NULL) AND (edge_kind IS NULL) AND (edge_source_kind IS NULL) AND (edge_source_id IS NULL) AND (edge_target_kind IS NULL) AND (edge_target_id IS NULL) AND (NOT ((supersedes_memory_id IS NOT NULL) AND (supersedes_goal_id IS NOT NULL))))
END),
    CONSTRAINT change_event_owner_ref_shape_chk CHECK ((((owner_kind = 'world'::proxima_core.owner_ref_kind) AND (owner_id IS NULL)) OR ((owner_kind = ANY (ARRAY['personal'::proxima_core.owner_ref_kind, 'group'::proxima_core.owner_ref_kind])) AND (owner_id IS NOT NULL)))),
    CONSTRAINT change_event_world_not_write_owner_chk CHECK ((owner_kind <> 'world'::proxima_core.owner_ref_kind))
);


--
-- Name: CONSTRAINT change_event_endpoint_chk ON change_event; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON CONSTRAINT change_event_endpoint_chk ON proxima_core.change_event IS 'Guards the pull-read decode (change_event.rs). EdgeAppend/EdgeDelete rows carry the whole edge — source (kind, id), target (kind, id), edge kind — and no entity/supersedes columns. EntityAppend/EntityDelete rows carry exactly one of entity_memory_id/entity_goal_id plus entity_kind/schema, at most one supersedes endpoint, and no edge columns. Keeps a raw INSERT from persisting an undecodable row.';


