--
-- Name: goals; Type: TABLE; Schema: proxima_core; Owner: -
--

CREATE TABLE proxima_core.goals (
    goal_id uuid NOT NULL,
    schema_id text NOT NULL,
    owner_kind proxima_core.owner_ref_kind NOT NULL,
    owner_id uuid,
    text text NOT NULL,
    state proxima_core.goal_state NOT NULL,
    supersedes uuid,
    authorship_kind proxima_core.goal_authorship_kind NOT NULL,
    authorship_origin proxima_core.goal_authorship_origin,
    authorship_operator_id uuid,
    authorship_tool_id text,
    operator_kind proxima_core.goal_operator_kind,
    input_contract_id uuid,
    model_id text,
    prompt_version text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    request_id text NOT NULL,
    idempotency_key text NOT NULL,
    schema_version integer NOT NULL,
    payload bytea NOT NULL,
    title text NOT NULL,
    superseded_by uuid,
    assignment_perspective_id uuid,
    dependency_goal_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    evidence_memory_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    CONSTRAINT goals_authorship_shape_chk CHECK ((((authorship_kind = 'User'::proxima_core.goal_authorship_kind) AND (authorship_origin IS NULL) AND (authorship_operator_id IS NULL) AND (authorship_tool_id IS NULL) AND (operator_kind IS NULL) AND (input_contract_id IS NULL) AND (model_id IS NULL) AND (prompt_version IS NULL)) OR ((authorship_kind = 'System'::proxima_core.goal_authorship_kind) AND (authorship_origin = 'Operator'::proxima_core.goal_authorship_origin) AND (authorship_operator_id IS NOT NULL) AND (operator_kind IS NOT NULL) AND (input_contract_id IS NOT NULL) AND (model_id IS NOT NULL) AND (prompt_version IS NOT NULL) AND (authorship_tool_id IS NULL)) OR ((authorship_kind = 'System'::proxima_core.goal_authorship_kind) AND (authorship_origin = 'Tool'::proxima_core.goal_authorship_origin) AND (authorship_tool_id IS NOT NULL) AND (authorship_operator_id IS NULL) AND (operator_kind IS NULL) AND (input_contract_id IS NULL) AND (model_id IS NULL) AND (prompt_version IS NULL)) OR ((authorship_kind = 'External'::proxima_core.goal_authorship_kind) AND (authorship_origin IS NULL) AND (authorship_operator_id IS NULL) AND (authorship_tool_id IS NULL) AND (operator_kind IS NULL) AND (input_contract_id IS NULL) AND (model_id IS NULL) AND (prompt_version IS NULL)))),
    CONSTRAINT goals_owner_ref_shape_chk CHECK ((((owner_kind = 'world'::proxima_core.owner_ref_kind) AND (owner_id IS NULL)) OR ((owner_kind = ANY (ARRAY['personal'::proxima_core.owner_ref_kind, 'group'::proxima_core.owner_ref_kind])) AND (owner_id IS NOT NULL)))),
    CONSTRAINT goals_payload_nonempty_chk CHECK ((octet_length(payload) > 0)),
    CONSTRAINT goals_request_id_nonempty CHECK ((length(btrim(request_id)) > 0)),
    CONSTRAINT goals_schema_version_positive_chk CHECK ((schema_version > 0)),
    CONSTRAINT goals_superseded_by_not_self_chk CHECK ((superseded_by IS DISTINCT FROM goal_id)),
    CONSTRAINT goals_text_nonempty CHECK ((length(btrim(text)) > 0)),
    CONSTRAINT goals_title_nonempty CHECK ((length(btrim(title)) > 0))
);


--
-- Name: TABLE goals; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON TABLE proxima_core.goals IS 'The Goal node kind (desired end-states), kept out of memories because it carries a lifecycle and authorship model. Goal topology is ordinary proxima_core.edges. See docs/06-goals-and-self.md. Unlike every owner-shadow table (edges, embeddings, fact_receipts, change_event, ...), this table intentionally carries no world_not_write_owner_chk since v0.0.5: owner_kind = world is the persisted result of a deliberate publish-to-World owner transfer (Engine::publish_to_world), not a fresh write under World. goals_owner_ref_shape_chk still enforces the owner_kind/owner_id shape; the engine authz layer (authorize_write) is the sole enforcement point blocking fresh writes with a World owner.';


--
-- Name: COLUMN goals.input_contract_id; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.goals.input_contract_id IS 'Opaque input contract id for A→Goal OperatorInvocation proof carriers; NULL for non-operator authorship.';


--
-- Name: COLUMN goals.assignment_perspective_id; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.goals.assignment_perspective_id IS 'The self Perspective this Goal inspires (was the core/inspires edge). One reference row is derived from it.';


--
-- Name: COLUMN goals.dependency_goal_ids; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.goals.dependency_goal_ids IS 'Goals this one waits on (was core/depends-on). One reference row per entry.';


--
-- Name: COLUMN goals.evidence_memory_ids; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.goals.evidence_memory_ids IS 'Memories this Goal rests on (was core/wake-motivated-by). One reference row per entry.';


--
-- Name: CONSTRAINT goals_payload_nonempty_chk ON goals; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON CONSTRAINT goals_payload_nonempty_chk ON proxima_core.goals IS 'Defense-in-depth against zero-byte goal-key payloads. Every registered Goal schema produces non-empty schema-owned key material. Engine GoalWrite validates the payload against its registered schema before storage; this CHECK is the last line of defense if a zero-byte key reaches storage by another path. Replaces the former DEFAULT ''\x'' which silently admitted empty payloads.';


--
-- Name: CONSTRAINT goals_request_id_nonempty ON goals; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON CONSTRAINT goals_request_id_nonempty ON proxima_core.goals IS 'Goal writes are idempotent per Owner/request_id; empty request ids are never valid.';


--
-- Name: CONSTRAINT goals_text_nonempty ON goals; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON CONSTRAINT goals_text_nonempty ON proxima_core.goals IS 'Goal text is the retrieval body for the Goal node and must be nonblank.';


--
-- Name: CONSTRAINT goals_title_nonempty ON goals; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON CONSTRAINT goals_title_nonempty ON proxima_core.goals IS 'Goal title is the compact display label for the Goal node and must be nonblank.';


