    CONSTRAINT mcp_call_logged_v1_io_content_hash_len_chk CHECK ((octet_length(io_content_hash) = 32)),
    CONSTRAINT mcp_call_logged_v1_latency_ms_chk CHECK ((latency_ms >= 0))
);


--
-- Name: memories; Type: TABLE; Schema: proxima_core; Owner: -
--

CREATE TABLE proxima_core.memories (
    memory_id uuid NOT NULL,
    fact_entity_id uuid,
    owner_kind proxima_core.owner_ref_kind NOT NULL,
    owner_id uuid,
    schema_id text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    receipt_id bytea,
    citation_mapping_id uuid,
    kind proxima_core.entity_kind,
    text text,
    operator_kind proxima_core.memory_operator_kind,
    operator_id uuid,
    input_contract_id uuid,
    source_batch_id uuid,
    model_id text,
    prompt_version text,
    supersedes uuid,
    schema_version integer NOT NULL,
    tombstoned_at timestamp with time zone,
    lexical_language regconfig DEFAULT proxima_core.lexical_config() NOT NULL,
    search_tsv tsvector GENERATED ALWAYS AS (proxima_core.lexical_tsv(lexical_language, COALESCE(text, ''::text))) STORED,
    superseded_by uuid,
    authoring_perspective_id uuid,
    CONSTRAINT memories_authoring_perspective_not_self_chk CHECK ((authoring_perspective_id IS DISTINCT FROM memory_id)),
    CONSTRAINT memories_fact_entity_chk CHECK (((fact_entity_id IS NULL) OR (kind IS NULL))),
    CONSTRAINT memories_kind_values_chk CHECK (((kind IS NULL) OR (kind = ANY (ARRAY['Abstraction'::proxima_core.entity_kind, 'Perspective'::proxima_core.entity_kind])))),
    CONSTRAINT memories_owner_ref_shape_chk CHECK ((((owner_kind = 'world'::proxima_core.owner_ref_kind) AND (owner_id IS NULL)) OR ((owner_kind = ANY (ARRAY['personal'::proxima_core.owner_ref_kind, 'group'::proxima_core.owner_ref_kind])) AND (owner_id IS NOT NULL)))),
    CONSTRAINT memories_schema_version_positive_chk CHECK ((schema_version > 0)),
    CONSTRAINT memories_superseded_by_not_a_fact_chk CHECK (((superseded_by IS NULL) OR (kind IS NOT NULL))),
    CONSTRAINT memories_superseded_by_not_self_chk CHECK ((superseded_by IS DISTINCT FROM memory_id)),
    CONSTRAINT memories_variant_chk CHECK ((((kind IS NULL) AND (operator_kind IS NULL) AND (operator_id IS NULL) AND (input_contract_id IS NULL) AND (source_batch_id IS NULL) AND (model_id IS NULL) AND (prompt_version IS NULL) AND (supersedes IS NULL)) OR ((kind IS NOT NULL) AND (text IS NOT NULL) AND (operator_kind IS NOT NULL) AND (operator_id IS NOT NULL) AND (input_contract_id IS NOT NULL) AND (((operator_kind = 'FtoA'::proxima_core.memory_operator_kind) AND (kind = 'Abstraction'::proxima_core.entity_kind) AND (source_batch_id IS NOT NULL)) OR ((operator_kind = 'AtoA'::proxima_core.memory_operator_kind) AND (kind = 'Abstraction'::proxima_core.entity_kind) AND (source_batch_id IS NULL)) OR ((operator_kind = 'AtoP'::proxima_core.memory_operator_kind) AND (kind = 'Perspective'::proxima_core.entity_kind) AND (source_batch_id IS NULL))) AND (model_id IS NOT NULL) AND (prompt_version IS NOT NULL) AND (receipt_id IS NULL) AND ((citation_mapping_id IS NULL) OR (kind = 'Abstraction'::proxima_core.entity_kind)))))
);


--
-- Name: TABLE memories; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON TABLE proxima_core.memories IS 'Graph nodes of kind Fact | Abstraction | Perspective (the fourth node kind, Goal, lives in goals). Discriminated by the kind column via memories_variant_chk: Fact rows have kind NULL, optional receipt_id, optional citation_mapping_id, and no operator fields; Abstraction (FtoA operator) and Perspective (AtoP operator) = kind set, operator-derived (operator_kind/model_id/prompt_version), with no receipt_id or citation. See docs/02-memory.md for the Fact -> Abstraction -> Perspective -> Goal derivation pipeline. Unlike every owner-shadow table (edges, embeddings, fact_receipts, change_event, ...), this table intentionally carries no world_not_write_owner_chk since v0.0.5: owner_kind = world is the persisted result of a deliberate publish-to-World owner transfer (Engine::publish_to_world), not a fresh write under World. memories_owner_ref_shape_chk still enforces the owner_kind/owner_id shape; the engine authz layer (authorize_write) is the sole enforcement point blocking fresh writes with a World owner.';


--
-- Name: COLUMN memories.receipt_id; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.memories.receipt_id IS 'Optional on Facts: the source fact receipt (proxima_core.fact_receipts) this Fact was ingested from when receipt metadata exists. NULL on receiptless Facts and on Abstractions/Perspectives.';


--
-- Name: COLUMN memories.citation_mapping_id; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.memories.citation_mapping_id IS 'Optional outside-proof for a Fact or an Abstraction (-> citation_mappings). An Abstraction cites the record of the computation that produced it. Forbidden on Perspectives, which ground through their references.';


--
-- Name: COLUMN memories.kind; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.memories.kind IS 'NULL => Fact; otherwise Abstraction or Perspective (constrained by memories_kind_values_chk + memories_variant_chk).';


--
-- Name: COLUMN memories.operator_id; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.memories.operator_id IS 'Opaque operator id for PR7 OperatorInvocation proof carriers on derived memories.';


--
-- Name: COLUMN memories.input_contract_id; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.memories.input_contract_id IS 'Opaque input contract id for PR7 OperatorInvocation proof carriers on derived memories.';


--
-- Name: COLUMN memories.source_batch_id; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.memories.source_batch_id IS 'Closed source batch id for F→A derived Abstractions; NULL for A→A/A→P.';


--
-- Name: COLUMN memories.lexical_language; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.memories.lexical_language IS 'Text-search configuration this row''s text is tokenised with. Stamped at write time (explicit caller choice, reliable detection, or the database default) and immutable afterwards, like the text it describes.';


--
-- Name: COLUMN memories.superseded_by; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.memories.superseded_by IS 'The revision that replaced this row, when one has. The inverse of supersedes, kept on the row so "is this the head?" is a column read rather than an index traversal. Facts are never superseded.';


--
-- Name: COLUMN memories.authoring_perspective_id; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON COLUMN proxima_core.memories.authoring_perspective_id IS 'The Perspective that emitted this memory, when one did. Replaces the core/authored edge and its authorship mask: authorship of a node is a property of the node.';


--
-- Name: owner_fact_retention; Type: TABLE; Schema: proxima_core; Owner: -
--

CREATE TABLE proxima_core.owner_fact_retention (
    owner_kind proxima_core.owner_ref_kind NOT NULL,
    owner_id uuid NOT NULL,
    retention_seconds bigint NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT owner_fact_retention_owner_ref_shape_chk CHECK ((((owner_kind = 'world'::proxima_core.owner_ref_kind) AND (owner_id IS NULL)) OR ((owner_kind = ANY (ARRAY['personal'::proxima_core.owner_ref_kind, 'group'::proxima_core.owner_ref_kind])) AND (owner_id IS NOT NULL)))),
    CONSTRAINT owner_fact_retention_retention_seconds_check CHECK ((retention_seconds > 0)),
    CONSTRAINT owner_fact_retention_world_not_write_owner_chk CHECK ((owner_kind <> 'world'::proxima_core.owner_ref_kind))
);


--
-- Name: owner_legal_holds; Type: TABLE; Schema: proxima_core; Owner: -
--

CREATE TABLE proxima_core.owner_legal_holds (
    owner_kind proxima_core.owner_ref_kind NOT NULL,
    owner_id uuid NOT NULL,
    hold_active boolean DEFAULT true NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT owner_legal_holds_active_chk CHECK (hold_active),
    CONSTRAINT owner_legal_holds_owner_ref_shape_chk CHECK ((((owner_kind = 'world'::proxima_core.owner_ref_kind) AND (owner_id IS NULL)) OR ((owner_kind = ANY (ARRAY['personal'::proxima_core.owner_ref_kind, 'group'::proxima_core.owner_ref_kind])) AND (owner_id IS NOT NULL)))),
    CONSTRAINT owner_legal_holds_world_not_write_owner_chk CHECK ((owner_kind <> 'world'::proxima_core.owner_ref_kind))
);


--
-- Name: TABLE owner_legal_holds; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON TABLE proxima_core.owner_legal_holds IS 'Owner-scoped legal/security holds. A present row is an active hold and blocks only physical compliance erase transactions for that owner; reads, writes, abandonment law, and suppression law are unchanged. Operators own the legal judgment behind setting or clearing the hold.';


--
-- Name: resolved_group_memberships; Type: VIEW; Schema: proxima_core; Owner: -
