    CONSTRAINT source_cursors_world_not_write_owner_chk CHECK ((owner_kind <> 'world'::proxima_core.owner_ref_kind))
);


--
-- Name: TABLE source_cursors; Type: COMMENT; Schema: proxima_core; Owner: -
--

COMMENT ON TABLE proxima_core.source_cursors IS 'Owner-scoped opaque source resume cursors for host projectors. Proxima persists and returns cursor bytea verbatim; it never interprets, validates, decodes, normalizes, or derives ordering from cursor bytes. Fresh writes remain engine-authorized owner writes; World cannot own cursor rows.';


